"""Operations on patients: what each one checks before it writes."""

from collections.abc import Mapping
from typing import Any

from app.documents import problems
from app.entities.patient import Patient, PatientContact
from app.errors import ConflictError, FieldError, NotFoundError, ValidationFailedError
from app.paging import Page
from app.unit_of_work import UnitOfWork

# Columns a client may send: the database fills the others
_FIELDS = frozenset({"name", "birth", "weight", "balance", "document", "photo", "visits", "blood", "contacts", "insurance", "version"})

# What the documents inside each field must be
_RULES: dict[str, dict[str, Any]] = {
    "contacts": {"items": {"fields": {"kind": {"required": True, "values": ["phone", "email"]}, "value": {"required": True}}}},
    "insurance": {"fields": {"company": {}, "since": {}}},
}


class PatientService:
    """Operations on patients. Repositories commit every write."""

    def __init__(self, uow: UnitOfWork) -> None:
        self._uow = uow

    async def _validate_all(self, values: dict[str, Any], current: Patient | None) -> None:
        """Checks the values against the rules of the "patients" table; raises ValidationFailedError with every problem."""
        creating = current is None
        errors: list[FieldError] = []
        for name in values.keys() - _FIELDS:
            errors.append(FieldError(name, "is not a field of Patient"))
        if not creating:
            for name in values.keys() & {"id", "version"}:
                errors.append(FieldError(name, "cannot be changed"))
        value = values.get("name")
        if value is None:
            if creating or "name" in values:
                errors.append(FieldError("name", "is required"))
        else:
            if isinstance(value, str) and len(value) > 80:
                errors.append(FieldError("name", "is longer than 80 characters"))
            if not len(value) >= 2:
                errors.append(FieldError("name", "must have >= 2 characters"))
        value = values.get("birth")
        if value is None:
            if creating or "birth" in values:
                errors.append(FieldError("birth", "is required"))
        value = values.get("visits")
        if value is None:
            if creating or "visits" in values:
                errors.append(FieldError("visits", "is required"))
        else:
            if not value >= 0:
                errors.append(FieldError("visits", "must be >= 0"))
        value = values.get("blood")
        if value is not None:
            if value not in ("A", "B", "O",):
                errors.append(FieldError("blood", "must be one of: A, B, O"))
        value = values.get("contacts")
        if value is None:
            if creating or "contacts" in values:
                errors.append(FieldError("contacts", "is required"))
        else:
            errors += problems(value, _RULES["contacts"], "contacts")
        value = values.get("insurance")
        if value is not None:
            errors += problems(value, _RULES["insurance"], "insurance")
        if errors:
            raise ValidationFailedError("Patient", errors)

    async def _check_unique(self, values: dict[str, Any], current: Patient | None) -> None:
        """Values that must be unique are not taken by another row."""
        document = values["document"] if "document" in values else (current.document if current is not None else None)
        if document is not None:
            other = await self._uow.patients.find_by_document(document)
            if other is not None and (current is None or other.id != current.id):
                raise ConflictError("Patient", "document is already taken", ("document",))

    async def _check(self, values: dict[str, Any], current: Patient | None) -> None:
        """Every check before a write: the values, the rows they point to, the unique values."""
        await self._validate_all(values, current)
        await self._check_unique(values, current)

    async def _find(self, id: str) -> Patient:
        """The Patient with this key; NotFoundError when there is none."""
        entity = await self._uow.patients.find_by_id(id)
        if entity is None:
            raise NotFoundError("Patient", id)
        return entity

    async def create_patient(self, patient: Patient) -> Patient:
        """Stores a new Patient after checking it."""
        values = {name: getattr(patient, name) for name in _FIELDS}
        await self._check(values, None)
        created = await self._uow.patients.insert(patient)
        return created

    async def get_patient(self, id: str) -> Patient:
        """The Patient with this key; NotFoundError when there is none."""
        return await self._find(id)

    async def list_patients(self, offset: int = 0, limit: int = 50) -> Page[Patient]:
        """A page of patients, by primary key."""
        return await self._uow.patients.list(offset, limit)

    async def update_patient(self, id: str, changes: Mapping[str, Any], version: int) -> Patient:
        """Changes the given values of a Patient, read at `version`."""
        values = dict(changes)
        current = await self._find(id)
        if current.version != version:
            raise ConflictError("Patient", "was changed by someone else since it was read", ("version",))
        await self._check(values, current)
        for name, value in values.items():
            setattr(current, name, value)
        current.version = version + 1
        updated = await self._uow.patients.update(current)
        return updated

    async def delete_patient(self, id: str, version: int) -> None:
        """Deletes a Patient."""
        current = await self._find(id)
        if current.version != version:
            raise ConflictError("Patient", "was changed by someone else since it was read", ("version",))
        await self._uow.patients.delete(current)

    async def find_patient_by_document(self, document: str) -> Patient | None:
        """The Patient with this document, or None."""
        return await self._uow.patients.find_by_document(document)

    async def add_contact(self, id: str, contact: PatientContact, version: int) -> Patient:
        """Adds an item to contacts, read at `version`."""
        errors = problems([contact], _RULES["contacts"], "contacts")
        if errors:
            raise ValidationFailedError("Patient", errors)
        current = await self._find(id)
        if current.version != version:
            raise ConflictError("Patient", "was changed by someone else since it was read", ("version",))
        changed = await self._uow.patients.add_contact(id, contact)
        if changed is None:
            raise NotFoundError("Patient", id)
        return changed

    async def remove_contact(self, id: str, position: int, version: int) -> Patient:
        """Removes an item from contacts, by its position, read at `version`."""
        current = await self._find(id)
        if current.version != version:
            raise ConflictError("Patient", "was changed by someone else since it was read", ("version",))
        if not (0 <= position < len(current.contacts or [])):
            raise NotFoundError("Contact", position)
        changed = await self._uow.patients.remove_contact(id, position, len(current.contacts))
        if changed is None:
            raise ConflictError("Patient", "was changed by someone else since it was read", ("contacts",))
        return changed

