"""Rows for the tests: valid values for every column, and the rows they point to."""

from datetime import UTC, datetime
from decimal import Decimal
from typing import Any

from app.entities.patient import Patient
from app.entities.room import Room
from app.unit_of_work import UnitOfWork


def new_patient(n: int = 1, **values: Any) -> Patient:
    """A valid Patient that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"name": f"name-{n}", "birth": datetime(2026, 1, n % 28 + 1, 12, 0, 0, tzinfo=UTC), "weight": n + 0.5, "balance": Decimal(f"{n % 10000}.50"), "document": f"document-{n}", "photo": bytes([n % 256]), "visits": n, "blood": "A", "contacts": [{"kind": "phone", "value": f"value-{n}"}], "insurance": {"company": f"company-{n}", "since": datetime(2026, 1, n % 28 + 1, 12, 0, 0, tzinfo=UTC)}, "version": n}
    return Patient(**(defaults | values))


async def add_patient(uow: UnitOfWork, n: int = 1) -> Patient:
    """A stored Patient."""
    return await uow.patients.insert(new_patient(n))


def new_room(n: int = 1, **values: Any) -> Room:
    """A valid Room that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"code": f"code-{n}", "beds": n}
    return Room(**(defaults | values))


async def add_room(uow: UnitOfWork, n: int = 1) -> Room:
    """A stored Room."""
    return await uow.rooms.insert(new_room(n))
